//! Translations. Each language is a plain text file in `lang/` (one
//! `key = text` per line). All of them are embedded at build time, and a file
//! with the same name in a `lang` folder next to crow.exe takes precedence, so
//! translators can try their work without building anything.

use crate::ffi::*;
use crate::util::*;
use alloc::boxed::Box;
use alloc::string::String;
use alloc::vec::Vec;

// Generated by build.rs: `pub static LANGS: &[(&str, &str)] = &[(code, text), ...];`
include!(concat!(env!("OUT_DIR"), "/langs.rs"));

struct Table {
    code: &'static str,
    pairs: Vec<(&'static str, &'static str)>,
}

static mut CUR: Option<Table> = None;
static mut EN: Option<Table> = None;

fn parse(text: &'static str) -> Vec<(&'static str, &'static str)> {
    let mut v = Vec::new();
    for line in text.lines() {
        let line = line.trim().trim_start_matches('\u{feff}');
        if line.is_empty() || line.starts_with(';') || line.starts_with('#') {
            continue;
        }
        if let Some(eq) = line.find('=') {
            v.push((line[..eq].trim(), line[eq + 1..].trim()));
        }
    }
    v
}

fn lookup(t: &Table, key: &str) -> Option<&'static str> {
    t.pairs.iter().find(|p| p.0 == key).map(|p| p.1)
}

/// Folder next to crow.exe where translators can drop language files.
fn external_dir() -> WString {
    let mut buf = [0u16; 520];
    let n = unsafe { GetModuleFileNameW(0, buf.as_mut_ptr(), 520) } as usize;
    wcat(&[parent_dir(&buf[..n]), w!("\\lang")])
}

fn external(code: &str) -> Option<&'static str> {
    let p = wcat(&[&external_dir(), w!("\\"), &to_w(code), w!(".ini")]);
    let data = read_file_max(&p, 256 << 10)?;
    let s = String::from_utf8(data).ok()?;
    Some(Box::leak(s.into_boxed_str()))
}

fn text_for(code: &str) -> Option<(&'static str, &'static str)> {
    if let Some(t) = external(code) {
        // keep the embedded code string when there is one, otherwise leak a copy
        let c = LANGS.iter().find(|l| l.0.eq_ignore_ascii_case(code)).map(|l| l.0)
            .unwrap_or_else(|| Box::leak(String::from(code).into_boxed_str()));
        return Some((c, t));
    }
    LANGS.iter().find(|l| l.0.eq_ignore_ascii_case(code)).map(|l| (l.0, l.1))
}

/// Language that matches the Windows display language.
pub fn detect() -> &'static str {
    let id = unsafe { GetUserDefaultUILanguage() } as u32;
    match id & 0x3FF {
        0x16 => "pt-BR",
        0x0A => "es",
        0x19 => "ru",
        0x04 => match id {
            0x0404 | 0x0C04 | 0x1404 => "zh-Hant",
            _ => "zh-Hans",
        },
        _ => "en",
    }
}

/// Switches the language. `auto` follows Windows.
pub fn set(code: &str) {
    let want = if code.is_empty() || code.eq_ignore_ascii_case("auto") { detect() } else { code };
    let (c, text) = text_for(want).or_else(|| text_for("en")).unwrap_or(("en", ""));
    unsafe {
        let en = &mut *core::ptr::addr_of_mut!(EN);
        if en.is_none() {
            if let Some((ec, et)) = text_for("en") {
                *en = Some(Table { code: ec, pairs: parse(et) });
            }
        }
        *core::ptr::addr_of_mut!(CUR) = Some(Table { code: c, pairs: parse(text) });
    }
}

/// Code of the language in use.
pub fn current() -> &'static str {
    unsafe { (*core::ptr::addr_of!(CUR)).as_ref().map_or("en", |t| t.code) }
}

/// Translated text for `key`, falling back to English and then to the key.
pub fn tr(key: &'static str) -> &'static str {
    unsafe {
        if (*core::ptr::addr_of!(CUR)).is_none() {
            set("auto");
        }
        if let Some(v) = (*core::ptr::addr_of!(CUR)).as_ref().and_then(|t| lookup(t, key)) {
            return v;
        }
        if let Some(v) = (*core::ptr::addr_of!(EN)).as_ref().and_then(|t| lookup(t, key)) {
            return v;
        }
    }
    key
}

/// Every available language as (code, native name), embedded ones first and
/// then any extra files a translator put in the `lang` folder.
pub fn available() -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = Vec::new();
    for &(code, text) in LANGS {
        let t = external(code).unwrap_or(text);
        let name = parse(t).iter().find(|p| p.0 == "@name").map_or(code, |p| p.1);
        out.push((code.into(), name.into()));
    }
    for f in list_files(&external_dir()) {
        if !ext_is(&f, "ini") {
            continue;
        }
        let code = from_w(stem(&f));
        if out.iter().any(|o| o.0.eq_ignore_ascii_case(&code)) {
            continue;
        }
        if let Some(t) = external(&code) {
            let name = parse(t).iter().find(|p| p.0 == "@name").map_or(code.clone(), |p| p.1.into());
            out.push((code, name));
        }
    }
    out
}
